type SectionId =
  | 'dashboard'
  | 'workbench'
  | 'training'
  | 'competition'
  | 'problems'
  | 'cases'
  | 'paper'
  | 'profile'

const NAV: { id: SectionId; label: string; icon: string; hint?: string }[] = [
  { id: 'dashboard', label: '仪表盘', icon: '📊' },
