  cases: { title: '案例', sub: '完整建模案例走读' },
  paper: { title: '论文', sub: '论文精读与差距分析' },
  profile: { title: '画像', sub: '个人掌握度画像' },
}

/* ---------- styles ---------- */

const S = {
  frame: {
    display: 'grid',
    gridTemplateColumns: '236px minmax(0, 1.15fr) minmax(380px, 1fr)',
    height: '100%',
    width: '100%',
    background: 'var(--dsh-bg, #141414)',
    color: 'inherit',
    overflow: 'hidden',
