  nav: {
    display: 'flex',
    flexDirection: 'column',
    minWidth: 0,
    borderRight: '1px solid rgba(128,128,128,0.25)',
    overflow: 'hidden',
  } as React.CSSProperties,
  brand: {
    padding: '14px 16px 12px',
    borderBottom: '1px solid rgba(128,128,128,0.22)',
  } as React.CSSProperties,
  brandTitle: {
    fontWeight: 700,
    fontSize: 15,
    letterSpacing: 0.2,
  } as React.CSSProperties,
  brandSub: {
    fontSize: 11,
    opacity: 0.55,
    marginTop: 3,
  } as React.CSSProperties,
  navList: {
    padding: '8px 8px',
    display: 'flex',
    flexDirection: 'column',
    gap: 2,
  } as React.CSSProperties,
  navItem: (active: boolean): React.CSSProperties => ({
