function loadNav(): SectionId {
  try {
    const v = sessionStorage.getItem(NAV_KEY) as SectionId | null
    if (v && NAV.some((n) => n.id === v)) return v
  } catch {
    /* storage unavailable */
  }
  return 'dashboard'
}

function saveNav(id: SectionId) {
  try {
    sessionStorage.setItem(NAV_KEY, id)
  } catch {
    /* ignore */
  }
}

/* ---------- dashboard ---------- */

type RegistryModel = {
  id: string
  name: string
  name_zh?: string
  difficulty?: string
  summary?: string
}

