      <div style={{ fontSize: 13, fontWeight: 700, marginTop: 24, marginBottom: 10 }}>模块入口</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(170px, 1fr))', gap: 10 }}>
        {modules.map((m) => (
