        background: pal.bg,
        display: agentOpen ? 'flex' : 'none',
        flexDirection: 'column',
        boxShadow: '-8px 0 28px rgba(0,0,0,0.22)',
      }
    : { ...S.chatCol, display: 'flex' }

  return (
    <div data-mm-shell="v3" style={narrow ? S.frameNarrow : S.frame}>
