    const sid = readCurrentSessionId()
    void fetch(`${API}/context`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ page: 'atlas', model_id: modelId, ...(sid ? { session_id: sid } : {}) }),
    }).catch(() => {})
    navigate('lesson')
