  const agentStyle: CSSProperties = narrow
    ? {
        position: 'fixed',
        top: 0,
        right: 0,
        bottom: 0,
        width: 'min(400px, 92vw)',
        zIndex: 70,
        background: pal.bg,
        display: agentOpen ? 'flex' : 'none',
