          {NAV.map((g) => (
            <div key={g.group}>
              <div style={S.navGroup}>{g.group}</div>
              {g.items.map((n) => (
                <div
                  key={n.id}
                  style={S.navItem(active === n.id)}
                  onClick={() => navigate(n.id)}
                  role="tab"
