{"content":"# Verify the mathmodel profile composition (dump-config) and optional live health.
param(
  [string]$ProfileName = "mathmodel",
  [int]$LivePort = 0
)

$ErrorActionPreference = "Stop"

$binCandidates = Get-ChildItem "$env:USERPROFILE\AppData\Local\npm-cache\_npx\*\node_modules\@deepseek-ai\dsh\lib\bin.js" -ErrorAction SilentlyContinue |
  Sort-Object LastWriteTime -Descending
if (-not $binCandidates) { throw "DSH installation not found" }
$DshBin = $binCandidates[0].FullName

Write-Host "[mm-verify] DSH version:" (& node $DshBin --version)

$tmp = New-TemporaryFile
& node $DshBin --profile $ProfileName --dump-config 2>$null | Out-File $tmp -Encoding utf8
$dump = Get-Content $tmp -Raw
Remove-Item $tmp -Force

$fail = @()
foreach ($must in @("@math-modeling/mathmodel-suite", "@math-modeling/mathmodel-shell", "@math-modeling/dsh-mathmodeling", "@deepseek-ai/dsh-web-app")) {
  if ($dump -notmatch [regex]::Escape($must)) { $fail += "missing: $must" }
}
if ($dump -match "@deepseek-ai/dsh-client-ui-layout") { $fail += "ui-layout must NOT be composed in mathmodel profile" }
if ($dump -match "linxin666|dshmarket|thinking-counter|openviking|vision-toolkit") { $fail += "community/user plugins leaked into product profile" }

if ($fail.Count -gt 0) {
  Write-Host "[mm-verify] FAIL:"
  $fail | ForEach-Object { Write-Host "  - $_" }
  exit 1
}
Write-Host "[mm-verify] dump-config composition OK (suite + shell + domain present; ui-layout & community plugins absent)"

if ($LivePort -gt 0) {
  $base = "http://127.0.0.1:$LivePort"
  foreach ($path in @("/api/mathmodeling/suite-health", "/api/mathmodeling/shell-v2/health", "/api/mathmodeling/health")) {
    $h = Invoke-RestMethod "$base$path" -TimeoutSec 10
    if (-not $h.ok) { throw "health failed: $path" }
  }
  Write-Host "[mm-verify] live health OK on :$LivePort"
}
Write-Host "[mm-verify] PASS"
","file_path":"C:\Users\Administrator\Projects\math-modeling-workbench\scripts\mathmodel-profile-verify.ps1"}

{"content":"# Start the mathmodel product instance (port 3100 by default).
param(
  [string]$ProfileName = "mathmodel",
  [int]$Port = 3100,
  [string]$DshBin = "",
  [switch]$Foreground
)

$ErrorActionPreference = "Stop"

if (-not $DshBin) {
  $candidates = Get-ChildItem "$env:USERPROFILE\AppData\Local\npm-cache\_npx\*\node_modules\@deepseek-ai\dsh\lib\bin.js" -ErrorAction SilentlyContinue |
    Sort-Object LastWriteTime -Descending
  if (-not $candidates) { throw "dsh bin.js not found in npx cache; pass -DshBin explicitly" }
  $DshBin = $candidates[0].FullName
}

if (Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue) {
  Write-Host "[mm-start] port $Port already listening — assuming instance is up"
  exit 0
}

# Correct CLI form for a custom profile: `dsh --profile <name> [--port N --no-open]`.
# (`web` is a hardcoded alias of `--profile web` and rejects parent flags.)
$args_ = @($DshBin, "--profile", $ProfileName, "--port", "$Port", "--no-open")
Write-Host "[mm-start] node $($args_ -join ' ')"

if ($Foreground) {
  node @args_
} else {
  $p = Start-Process -FilePath "node" -ArgumentList $args_ -WorkingDirectory $env:USERPROFILE -PassThru -WindowStyle Hidden
  Write-Host "[mm-start] started pid=$($p.Id); waiting for :$Port"
  $deadline = (Get-Date).AddSeconds(90)
  while ((Get-Date) -lt $deadline) {
    Start-Sleep -Milliseconds 1500
    if (Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue) {
      Write-Host "[mm-start] UP on http://127.0.0.1:$Port"
      exit 0
    }
    if ($p.HasExited) { throw "process exited early with code $($p.ExitCode)" }
  }
  throw "timeout waiting for port $Port"
}
","file_path":"C:\Users\Administrator\Projects\math-modeling-workbench\scripts\mathmodel-start.ps1"}

{"content":"# Remove the mathmodel product entirely: stop the instance, delete the profile dir.
# The `web` profile is NEVER touched.
param(
  [string]$ProfileName = "mathmodel",
  [int]$Port = 3100
)

$ErrorActionPreference = "Stop"

$conn = Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue | Select-Object -First 1
if ($conn) {
  $pidToStop = $conn.OwningProcess
  Write-Host "[mm-remove] stopping pid $pidToStop on :$Port"
  Stop-Process -Id $pidToStop -Force -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 1
} else {
  Write-Host "[mm-remove] nothing listening on :$Port"
}

$ProfileDir = Join-Path $env:USERPROFILE ".dsh\profiles\$ProfileName"
if (Test-Path $ProfileDir) {
  Remove-Item $ProfileDir -Recurse -Force
  Write-Host "[mm-remove] removed $ProfileDir"
} else {
  Write-Host "[mm-remove] profile dir not present"
}
Write-Host "[mm-remove] done. web profile untouched."
","file_path":"C:\Users\Administrator\Projects\math-modeling-workbench\scripts\mathmodel-remove.ps1"}

